using Og.Core.Runtime;

namespace Og.Core.Tests;

/// <summary>
/// Things people actually typed into the starter world and got nothing for:
/// "rest", "light the fire", "go soith", "kill the gobljn", "KILLL". Each of
/// these is somebody being perfectly clear and the parser being deaf.
/// </summary>
public class AskingPlainlyTests
{
    private const string Two = """
    {
      "spawnLocation": 1,
      "monsters": [
        { "name": "goblin", "description": "A goblin.", "hitPoints": 7, "armorClass": 12,
          "attackStrength": 1, "attackDice": 6 }
      ],
      "locations": [
        {
          "index": 1, "name": "Camp", "description": "An old camp. A cold firepit.",
          "connections": { "north": 2 },
          "interactions": [
            { "interactionId": "fire", "triggers": ["*fire*", "*rest*", "*sleep*"],
              "actions": [
                { "action": "describe", "parameters": ["The coal catches."] },
                { "action": "heal", "parameters": ["full"] }
              ] },
            { "interactionId": "bedroll", "triggers": ["*search*"],
              "actions": [ { "action": "describe", "parameters": ["Under the bedroll: armor."] } ] }
          ]
        },
        { "index": 2, "name": "Mouth", "description": "A cave mouth.", "connections": { "south": 1 },
          "monster": "goblin", "isExit": true }
      ]
    }
    """;

    private static (GameEngine, Session, CollectingOutputSink) Ready()
    {
        var engine = new GameEngine(World.FromJson(Two), new CollectingEventSink(), seed: 11);
        var output = new CollectingOutputSink();
        var session = engine.Enter("Tester", output);
        output.Clear();
        return (engine, session, output);
    }

    [Fact]
    public void AMistypedDirectionStillWalks()
    {
        var (engine, session, output) = Ready();

        engine.HandleInput(session, "go nrth");

        Assert.Contains("A cave mouth.", output.Text);
        Assert.Equal(2, session.CurrentLocationId);
    }

    [Fact]
    public void AWordThatIsNoDirectionAtAllIsToldWhichWaysAreOpen()
    {
        var (engine, session, output) = Ready();

        engine.HandleInput(session, "go forward");

        Assert.Contains("You can go north.", output.Text);
        Assert.Equal(1, session.CurrentLocationId);
    }

    [Fact]
    public void APlaceCanMendSomebody()
    {
        var (engine, session, output) = Ready();
        session.Character.HitPoints = 5;

        engine.HandleInput(session, "rest");

        Assert.Contains("The coal catches.", output.Text);
        Assert.Equal(session.Character.MaxHitPoints, session.Character.HitPoints);
    }

    [Fact]
    public void AndSaysSoWhenItCannot()
    {
        var (engine, session, output) = Ready();
        engine.HandleInput(session, "north");
        output.Clear();

        engine.HandleInput(session, "sleep");

        Assert.Contains("nowhere to rest", output.Text);
    }

    [Fact]
    public void SearchingReachesTheRoomEvenThoughLookingIsAVerb()
    {
        var (engine, session, output) = Ready();

        engine.HandleInput(session, "search");

        Assert.Contains("Under the bedroll: armor.", output.Text);
    }

    [Fact]
    public void AMisspelledCreatureIsStillTheOneInFrontOfYou()
    {
        var (engine, session, output) = Ready();
        engine.HandleInput(session, "north");
        output.Clear();

        engine.HandleInput(session, "kill the gobljn");

        Assert.True(output.Text.Contains("You hit") || output.Text.Contains("You missed"),
            $"expected a fight, got: {output.Text}");
    }

    [Fact]
    public void ACreatureThatIsNotThereIsNamedRatherThanShruggedAt()
    {
        var (engine, session, output) = Ready();
        engine.HandleInput(session, "north");
        output.Clear();

        engine.HandleInput(session, "kill the gombil");

        Assert.Contains("goblin is what is in front of you", output.Text);
    }

    [Fact]
    public void ASlippedKeyOnAVerbIsNotAMystery()
    {
        var (engine, session, output) = Ready();
        engine.HandleInput(session, "north");
        output.Clear();

        engine.HandleInput(session, "killl");

        Assert.True(output.Text.Contains("You hit") || output.Text.Contains("You missed"),
            $"expected a fight, got: {output.Text}");
    }

    [Fact]
    public void ButAWordThatMerelyLooksLikeADirectionIsNeverTakenForOne()
    {
        var (engine, session, _) = Ready();

        // "rest" is one letter from "west". Moving somebody who asked to sit down
        // would be worse than not understanding them.
        engine.HandleInput(session, "rest");

        Assert.Equal(1, session.CurrentLocationId);
    }
}

